				log.Printf("Ignoring reply to %d with no callback", body.InReplyTo)
				continue
			}

			// Handle callback in a separate goroutine.
			n.wg.Add(1)
			go func() {
				defer n.wg.Done()
				n.handleCallback(h, msg)
			}()
			continue
		}

		// If this is not a callback, ensure that a handler is registered.
		var h HandlerFunc
		if body.Type == "init" {
			h = n.handleInitMessage // wraps init message with special handling.
		} else if h = n.handlers[body.Type]; h == nil {
			return fmt.Errorf("No handler for %s", line)
		}

		// Handle message in a separate goroutine.
		n.wg.Add(1)
		go func() {
			defer n.wg.Done()
			n.handleMessage(h, msg)
		}()
	}
	if err := scanner.Err(); err != nil {
		return err
	}

	// Wait for all in-flight handlers to complete.
	n.wg.Wait()

	return nil
}

// handleCallback sends msg response to a callback function. Logs error, if one occurs.
func (n *Node) handleCallback(h HandlerFunc, msg Message) {
	if err := h(msg); err != nil {
		log.Printf("callback error: %s", err)
	}
}

// handleMessage sends msg to a handler function. Sends an RPC error if an error is returned.
func (n *Node) handleMessage(h HandlerFunc, msg Message) {
	if err := h(msg); err != nil {
		switch err := err.(type) {
		case *RPCError:
			if err := n.Reply(msg, err); err != nil {
				log.Printf("reply error: %s", err)
			}
		default:
			log.Printf("Exception handling %#v:\n%s", msg, err)
			if err := n.Reply(msg, NewRPCError(Crash, err.Error())); err != nil {
				log.Printf("reply error: %s", err)
			}
		}
	}
}

func (n *Node) handleInitMessage(msg Message) error {
	var body InitMessageBody
	if err := json.Unmarshal(msg.Body, &body); err != nil {
		return fmt.Errorf("unmarshal init message body: %w", err)
	}
	n.Init(body.NodeID, body.NodeIDs)

	// Delegate to application initialization handler, if specified.
	if h := n.handlers["init"]; h != nil {
		if err := h(msg); err != nil {
			return err
		}
	}

	// Send back a response that the node has been initialized.
	log.Printf("Node %s initialized", n.id)
	return n.Reply(msg, MessageBody{Type: "init_ok"})
}

// Reply replies to a request with a response body.
func (n *Node) Reply(req Message, body any) error {
	// Extract the message ID from the original message.
	var reqBody MessageBody
	if err := json.Unmarshal(req.Body, &reqBody); err != nil {
		return err
	}

	// We have to marshal/unmarshal to inject our reply message ID.
	b := make(map[string]any)
	if buf, err := json.Marshal(body); err != nil {
		return err
	} else if err := json.Unmarshal(buf, &b); err != nil {
		return err
	}
	b["in_reply_to"] = reqBody.MsgID

	return n.Send(req.Src, b)
}

// Send sends a message body to a given destination node.
func (n *Node) Send(dest string, body any) error {
	bodyJSON, err := json.Marshal(body)
	if err != nil {
		return err
	}

	buf, err := json.Marshal(Message{
		Src:  n.id,
		Dest: dest,
		Body: bodyJSON,
	})
	if err != nil {
		return err
	}

	// Synchronize access to STDOUT.
	n.mu.Lock()
	defer n.mu.Unlock()

	log.Printf("Sent %s", buf)

	if _, err = n.Stdout.Write(buf); err != nil {
		return err
	}
	_, err = n.Stdout.Write([]byte{'\n'})
	return err
}

// RPC sends an async RPC request. Handler invoked when response message received.
func (n *Node) RPC(dest string, body any, handler HandlerFunc) error {
	n.mu.Lock()

	// Generate a unique message ID.
	n.nextMsgID++
	msgID := n.nextMsgID

	// Register a handler for our callback.
	n.callbacks[msgID] = handler

	n.mu.Unlock()

	// We have to marshal/unmarshal to inject our message ID.
	b := make(map[string]any)
	if buf, err := json.Marshal(body); err != nil {
		return err
	} else if err := json.Unmarshal(buf, &b); err != nil {
		return err
	}
	b["msg_id"] = msgID

	return n.Send(dest, b)
}

// SyncRPC sends a synchronous RPC request. Returns the response message. RPC
// errors in the message body are converted to *RPCError and are returned.

package main

import (
	"context"
	"encoding/json"
	"log"
	"sync"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

// State is the authoritative state of every log.  In a two-node cluster we
// keep this state on one node and forward requests from the other node to it.
// That makes every send, poll, and committed-offset operation linearizable
// with respect to all clients.
type State struct {
	mu        sync.Mutex
	logs      map[string][]any
	committed map[string]int
}

func newState() *State {
	return &State{
		logs:      make(map[string][]any),
		committed: make(map[string]int),
	}
}

type sendRequest struct {
	Type string `json:"type"`
	Key  string `json:"key"`
	Msg  any    `json:"msg"`
}

type pollRequest struct {
	Type    string         `json:"type"`
	Offsets map[string]int `json:"offsets"`
}

type commitOffsetsRequest struct {
	Type    string         `json:"type"`
	Offsets map[string]int `json:"offsets"`
}

type listCommittedRequest struct {
	Type string   `json:"type"`
	Keys []string `json:"keys"`
}

func ownerID(n *maelstrom.Node) string {
	ids := n.NodeIDs()
	if len(ids) > 0 {
		return ids[0]
	}
	// Maelstrom always sends init before application requests, so this is only
	// a defensive fallback.
	return "n0"
}

// forward sends the original request body to the owner and relays the owner's
// response to the client.  The Node RPC machinery supplies a fresh message id
// for the forwarded request, so the client's original msg_id is not reused.
func forward(n *maelstrom.Node, req maelstrom.Message) error {
	var body map[string]any
	if err := json.Unmarshal(req.Body, &body); err != nil {
		return err
	}

	resp, err := n.SyncRPC(context.Background(), ownerID(n), body)
	if err != nil {
		return err
	}

	// resp.Body is the owner's response.  Reply replaces in_reply_to with the
	// original client message's id.
	return n.Reply(req, json.RawMessage(resp.Body))
}

func (s *State) append(key string, msg any) int {
	s.mu.Lock()
	defer s.mu.Unlock()

	off := len(s.logs[key])
	s.logs[key] = append(s.logs[key], msg)
	return off
}

func (s *State) poll(offsets map[string]int) map[string][][2]any {
	s.mu.Lock()
	defer s.mu.Unlock()

	out := make(map[string][][2]any)
	for key, start := range offsets {
		entries := s.logs[key]
		if start < 0 {
			start = 0
		}
		if start >= len(entries) {
			continue
		}

		pairs := make([][2]any, 0, len(entries)-start)
		for off := start; off < len(entries); off++ {
			pairs = append(pairs, [2]any{off, entries[off]})
		}
		if len(pairs) > 0 {
			out[key] = pairs
		}
	}
	return out
}

func (s *State) commit(offsets map[string]int) {
	s.mu.Lock()
	defer s.mu.Unlock()

	for key, off := range offsets {
		if old, ok := s.committed[key]; !ok || off > old {
			s.committed[key] = off
		}
	}
}

func (s *State) listCommitted(keys []string) map[string]int {
	s.mu.Lock()
	defer s.mu.Unlock()

	out := make(map[string]int)
	for _, key := range keys {
		if off, ok := s.committed[key]; ok {
			out[key] = off
		}
	}
	return out
}

func main() {
	n := maelstrom.NewNode()
	state := newState()

	n.Handle("send", func(msg maelstrom.Message) error {
		if n.ID() != ownerID(n) {
			return forward(n, msg)
		}

		var req sendRequest
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			return err
		}
		off := state.append(req.Key, req.Msg)
		return n.Reply(msg, map[string]any{
			"type":   "send_ok",
			"offset": off,
		})
	})

	n.Handle("poll", func(msg maelstrom.Message) error {
		if n.ID() != ownerID(n) {
			return forward(n, msg)
		}

		var req pollRequest
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			return err
		}
		return n.Reply(msg, map[string]any{
			"type": "poll_ok",
			"msgs": state.poll(req.Offsets),
		})
	})

	n.Handle("commit_offsets", func(msg maelstrom.Message) error {
		if n.ID() != ownerID(n) {
			return forward(n, msg)
		}

		var req commitOffsetsRequest
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			return err
		}
		state.commit(req.Offsets)
		return n.Reply(msg, map[string]any{"type": "commit_offsets_ok"})
	})

	n.Handle("list_committed_offsets", func(msg maelstrom.Message) error {
		if n.ID() != ownerID(n) {
			return forward(n, msg)
		}

		var req listCommittedRequest
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			return err
		}
		return n.Reply(msg, map[string]any{
			"type":    "list_committed_offsets_ok",
			"offsets": state.listCommitted(req.Keys),
		})
	})

	if err := n.Run(); err != nil {
		log.Fatal(err)
	}
}

